//! Ceremony transcript and attestation helper for trusted setup contributions.
//!
//! This binary does not perform cryptographic phase2 itself. It records and
//! verifies contribution transitions on top of CRS bundles generated by an
//! external phase2 flow.

use std::fs::File;
use std::io::{BufReader, BufWriter, Read, Write};
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

use clap::{Parser, Subcommand};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use zoka::zk::setup_io;

#[derive(Debug, Parser)]
#[command(
    name = "zoka-ceremony-contribute",
    about = "Manage trusted-setup ceremony transcript and contribution attestations"
)]
struct Cli {
    #[command(subcommand)]
    command: Command,
}

#[derive(Debug, Subcommand)]
enum Command {
    /// Initialize a transcript from a starting trusted-setup directory.
    Init {
        /// Trusted setup directory with `*.params` and `DIGEST`.
        #[arg(long)]
        setup_dir: PathBuf,
        /// Output transcript path.
        #[arg(long)]
        transcript: PathBuf,
        /// Free-form label (ceremony name, network name, etc.).
        #[arg(long, default_value = "zoka-ceremony-v1")]
        label: String,
    },
    /// Append a contribution record from before->after bundles.
    Contribute {
        #[arg(long)]
        before_dir: PathBuf,
        #[arg(long)]
        after_dir: PathBuf,
        #[arg(long)]
        transcript: PathBuf,
        /// Contributor identifier (name, handle, key fingerprint).
        #[arg(long)]
        contributor: String,
        /// Optional contribution note.
        #[arg(long, default_value = "")]
        note: String,
    },
    /// Verify transcript integrity and optional final bundle digest match.
    Verify {
        #[arg(long)]
        transcript: PathBuf,
        /// Optional final trusted setup directory expected to match transcript tail.
        #[arg(long)]
        final_dir: Option<PathBuf>,
    },
    /// Prepare adapter package for an external phase2 contribution tool.
    PrepareAdapter {
        /// Input trusted setup directory with canonical `*.params` + `DIGEST`.
        #[arg(long)]
        setup_dir: PathBuf,
        /// Working directory to materialize adapter package.
        #[arg(long)]
        adapter_dir: PathBuf,
        /// Free-form ceremony label.
        #[arg(long, default_value = "zoka-phase2-adapter-v1")]
        label: String,
        /// Overwrite existing adapter directory.
        #[arg(long)]
        force: bool,
    },
    /// Finalize adapter output into a canonical trusted setup directory.
    FinalizeAdapter {
        /// Adapter directory created by `prepare-adapter`.
        #[arg(long)]
        adapter_dir: PathBuf,
        /// Directory containing phase2 output `*.params`.
        #[arg(long)]
        phase2_out_dir: PathBuf,
        /// Canonical output setup directory where files + DIGEST are written.
        #[arg(long)]
        out_setup_dir: PathBuf,
        /// Optional transcript path to append contribution automatically.
        #[arg(long)]
        transcript: Option<PathBuf>,
        /// Contributor identifier if `--transcript` is provided.
        #[arg(long, default_value = "")]
        contributor: String,
        /// Optional note if `--transcript` is provided.
        #[arg(long, default_value = "")]
        note: String,
    },
    /// Emit release pin material for `ZOKA_EXPECTED_SETUP_DIGEST_COMPILED`.
    ReleasePin {
        /// Canonical trusted setup directory (`*.params` + `DIGEST`).
        #[arg(long)]
        setup_dir: PathBuf,
        /// Optional transcript path to verify tail digest consistency.
        #[arg(long)]
        transcript: Option<PathBuf>,
        /// Optional output dotenv-style file with export variables.
        #[arg(long)]
        out_env: Option<PathBuf>,
    },
    /// Check ceremony readiness (contributor threshold + digest consistency).
    Readiness {
        #[arg(long)]
        transcript: PathBuf,
        /// Canonical final setup directory expected to match transcript tail.
        #[arg(long)]
        final_dir: PathBuf,
        /// Minimum number of unique contributors required.
        #[arg(long, default_value_t = 5)]
        min_unique_contributors: usize,
        /// Optional JSON report output path.
        #[arg(long)]
        out_json: Option<PathBuf>,
    },
    /// Build a publishable ceremony bundle (transcript + final params + reports).
    PublishBundle {
        /// Ceremony transcript path.
        #[arg(long)]
        transcript: PathBuf,
        /// Canonical final setup directory expected to match transcript tail.
        #[arg(long)]
        final_dir: PathBuf,
        /// Output directory for publication bundle.
        #[arg(long)]
        out_dir: PathBuf,
        /// Minimum number of unique contributors required.
        #[arg(long, default_value_t = 5)]
        min_unique_contributors: usize,
        /// Overwrite output directory if it already exists.
        #[arg(long)]
        force: bool,
    },
    /// Verify a previously published ceremony bundle end-to-end.
    VerifyBundle {
        /// Bundle directory produced by `publish-bundle`.
        #[arg(long)]
        bundle_dir: PathBuf,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct SetupSnapshot {
    timestamp_unix: u64,
    directory: String,
    digest_hex: String,
    circuit_hashes: Vec<CircuitHash>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct CircuitHash {
    circuit: String,
    file: String,
    sha256: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ContributionRecord {
    index: usize,
    timestamp_unix: u64,
    contributor: String,
    note: String,
    before_digest_hex: String,
    after_digest_hex: String,
    before_circuit_hashes: Vec<CircuitHash>,
    after_circuit_hashes: Vec<CircuitHash>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct CeremonyTranscript {
    version: u32,
    label: String,
    created_at_unix: u64,
    genesis: SetupSnapshot,
    contributions: Vec<ContributionRecord>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct AdapterManifest {
    version: u32,
    label: String,
    created_at_unix: u64,
    source_setup_dir: String,
    source_digest_hex: String,
    source_circuit_hashes: Vec<CircuitHash>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ReadinessReport {
    transcript_path: String,
    final_dir: String,
    tail_digest_hex: String,
    final_digest_hex: String,
    contribution_count: usize,
    unique_contributors: usize,
    min_unique_contributors: usize,
    all_contributions_mutate_state: bool,
    ready: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct PublishedFile {
    relative_path: String,
    sha256: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct CeremonyPublicationManifest {
    version: u32,
    created_at_unix: u64,
    transcript_path: String,
    final_dir: String,
    final_digest_hex: String,
    min_unique_contributors: usize,
    unique_contributors: usize,
    contribution_count: usize,
    contributors: Vec<String>,
    files: Vec<PublishedFile>,
}

fn main() {
    let cli = Cli::parse();
    let result = match cli.command {
        Command::Init {
            setup_dir,
            transcript,
            label,
        } => init_transcript(&setup_dir, &transcript, &label),
        Command::Contribute {
            before_dir,
            after_dir,
            transcript,
            contributor,
            note,
        } => append_contribution(&before_dir, &after_dir, &transcript, &contributor, &note),
        Command::Verify {
            transcript,
            final_dir,
        } => verify_transcript(&transcript, final_dir.as_deref()),
        Command::PrepareAdapter {
            setup_dir,
            adapter_dir,
            label,
            force,
        } => prepare_adapter(&setup_dir, &adapter_dir, &label, force),
        Command::FinalizeAdapter {
            adapter_dir,
            phase2_out_dir,
            out_setup_dir,
            transcript,
            contributor,
            note,
        } => finalize_adapter(
            &adapter_dir,
            &phase2_out_dir,
            &out_setup_dir,
            transcript.as_deref(),
            &contributor,
            &note,
        ),
        Command::ReleasePin {
            setup_dir,
            transcript,
            out_env,
        } => release_pin(&setup_dir, transcript.as_deref(), out_env.as_deref()),
        Command::Readiness {
            transcript,
            final_dir,
            min_unique_contributors,
            out_json,
        } => readiness_check(
            &transcript,
            &final_dir,
            min_unique_contributors,
            out_json.as_deref(),
        ),
        Command::PublishBundle {
            transcript,
            final_dir,
            out_dir,
            min_unique_contributors,
            force,
        } => publish_bundle(
            &transcript,
            &final_dir,
            &out_dir,
            min_unique_contributors,
            force,
        ),
        Command::VerifyBundle { bundle_dir } => verify_bundle(&bundle_dir),
    };
    if let Err(err) = result {
        eprintln!("{err}");
        std::process::exit(1);
    }
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

fn params_path(dir: &Path, circuit: &str) -> Result<PathBuf, String> {
    let file = setup_io::params_filename(circuit).map_err(|e| e.to_string())?;
    Ok(dir.join(file))
}

fn file_sha256_hex(path: &Path) -> Result<String, String> {
    let mut file = File::open(path).map_err(|e| format!("opening {}: {}", path.display(), e))?;
    let mut hasher = Sha256::new();
    let mut buf = [0u8; 64 * 1024];
    loop {
        let n = file
            .read(&mut buf)
            .map_err(|e| format!("reading {}: {}", path.display(), e))?;
        if n == 0 {
            break;
        }
        hasher.update(&buf[..n]);
    }
    Ok(hex::encode(hasher.finalize()))
}

fn snapshot_setup(dir: &Path) -> Result<SetupSnapshot, String> {
    let digest = setup_io::verify_directory_digest(dir)
        .map_err(|e| format!("invalid trusted setup {}: {}", dir.display(), e))?;
    let mut circuit_hashes = Vec::new();
    for circuit in setup_io::REQUIRED_CIRCUITS {
        let path = params_path(dir, circuit)?;
        circuit_hashes.push(CircuitHash {
            circuit: circuit.to_string(),
            file: path
                .file_name()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_default(),
            sha256: file_sha256_hex(&path)?,
        });
    }
    Ok(SetupSnapshot {
        timestamp_unix: now_unix(),
        directory: dir.display().to_string(),
        digest_hex: hex::encode(digest),
        circuit_hashes,
    })
}

fn load_transcript(path: &Path) -> Result<CeremonyTranscript, String> {
    let file = File::open(path).map_err(|e| format!("opening {}: {}", path.display(), e))?;
    let reader = BufReader::new(file);
    serde_json::from_reader(reader).map_err(|e| format!("parsing {}: {}", path.display(), e))
}

fn save_transcript(path: &Path, transcript: &CeremonyTranscript) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() && !parent.exists() {
            std::fs::create_dir_all(parent)
                .map_err(|e| format!("creating {}: {}", parent.display(), e))?;
        }
    }
    let file = File::create(path).map_err(|e| format!("opening {}: {}", path.display(), e))?;
    let mut writer = BufWriter::new(file);
    serde_json::to_writer_pretty(&mut writer, transcript)
        .map_err(|e| format!("serializing transcript: {}", e))?;
    writer
        .write_all(b"\n")
        .map_err(|e| format!("writing {}: {}", path.display(), e))?;
    writer
        .flush()
        .map_err(|e| format!("flushing {}: {}", path.display(), e))?;
    Ok(())
}

fn init_transcript(setup_dir: &Path, transcript_path: &Path, label: &str) -> Result<(), String> {
    if transcript_path.exists() {
        return Err(format!(
            "transcript already exists at {} (refusing overwrite)",
            transcript_path.display()
        ));
    }
    let genesis = snapshot_setup(setup_dir)?;
    let transcript = CeremonyTranscript {
        version: 1,
        label: label.to_string(),
        created_at_unix: now_unix(),
        genesis,
        contributions: Vec::new(),
    };
    save_transcript(transcript_path, &transcript)?;
    println!(
        "initialized ceremony transcript at {}\nlabel: {}\ngenesis digest: {}",
        transcript_path.display(),
        transcript.label,
        transcript.genesis.digest_hex
    );
    Ok(())
}

fn transcript_tail_digest(transcript: &CeremonyTranscript) -> &str {
    transcript
        .contributions
        .last()
        .map(|c| c.after_digest_hex.as_str())
        .unwrap_or(transcript.genesis.digest_hex.as_str())
}

fn append_contribution(
    before_dir: &Path,
    after_dir: &Path,
    transcript_path: &Path,
    contributor: &str,
    note: &str,
) -> Result<(), String> {
    let mut transcript = load_transcript(transcript_path)?;
    let before = snapshot_setup(before_dir)?;
    let after = snapshot_setup(after_dir)?;

    let expected_before = transcript_tail_digest(&transcript);
    if before.digest_hex != expected_before {
        return Err(format!(
            "before digest mismatch: transcript expects {}, got {}",
            expected_before, before.digest_hex
        ));
    }
    if before.digest_hex == after.digest_hex {
        return Err("before and after digests are identical; no contribution detected".to_string());
    }

    let index = transcript.contributions.len();
    transcript.contributions.push(ContributionRecord {
        index,
        timestamp_unix: now_unix(),
        contributor: contributor.to_string(),
        note: note.to_string(),
        before_digest_hex: before.digest_hex,
        after_digest_hex: after.digest_hex.clone(),
        before_circuit_hashes: before.circuit_hashes,
        after_circuit_hashes: after.circuit_hashes,
    });

    save_transcript(transcript_path, &transcript)?;
    println!(
        "recorded contribution #{} by {}\nnew tail digest: {}",
        index, contributor, after.digest_hex
    );
    Ok(())
}

fn verify_transcript(transcript_path: &Path, final_dir: Option<&Path>) -> Result<(), String> {
    let transcript = load_transcript(transcript_path)?;
    if transcript.version != 1 {
        return Err(format!(
            "unsupported transcript version: {}",
            transcript.version
        ));
    }
    let mut expected = transcript.genesis.digest_hex.as_str();
    for rec in &transcript.contributions {
        if rec.before_digest_hex != expected {
            return Err(format!(
                "broken chain at contribution #{}: expected before {}, got {}",
                rec.index, expected, rec.before_digest_hex
            ));
        }
        expected = rec.after_digest_hex.as_str();
    }

    if let Some(dir) = final_dir {
        let final_snapshot = snapshot_setup(dir)?;
        if final_snapshot.digest_hex != expected {
            return Err(format!(
                "final dir digest mismatch: transcript tail {}, final dir {}",
                expected, final_snapshot.digest_hex
            ));
        }
    }

    println!(
        "transcript verified: {} contributions, tail digest {}",
        transcript.contributions.len(),
        expected
    );
    Ok(())
}

fn adapter_manifest_path(adapter_dir: &Path) -> PathBuf {
    adapter_dir.join("manifest.json")
}

fn write_adapter_manifest(path: &Path, manifest: &AdapterManifest) -> Result<(), String> {
    let file = File::create(path).map_err(|e| format!("opening {}: {}", path.display(), e))?;
    let mut writer = BufWriter::new(file);
    serde_json::to_writer_pretty(&mut writer, manifest)
        .map_err(|e| format!("serializing adapter manifest: {}", e))?;
    writer
        .write_all(b"\n")
        .map_err(|e| format!("writing {}: {}", path.display(), e))?;
    writer
        .flush()
        .map_err(|e| format!("flushing {}: {}", path.display(), e))?;
    Ok(())
}

fn read_adapter_manifest(path: &Path) -> Result<AdapterManifest, String> {
    let file = File::open(path).map_err(|e| format!("opening {}: {}", path.display(), e))?;
    let reader = BufReader::new(file);
    serde_json::from_reader(reader).map_err(|e| format!("parsing {}: {}", path.display(), e))
}

fn copy_required_params(src_dir: &Path, dst_dir: &Path) -> Result<(), String> {
    std::fs::create_dir_all(dst_dir)
        .map_err(|e| format!("creating {}: {}", dst_dir.display(), e))?;
    for circuit in setup_io::REQUIRED_CIRCUITS {
        let src = params_path(src_dir, circuit)?;
        let dst = params_path(dst_dir, circuit)?;
        std::fs::copy(&src, &dst)
            .map_err(|e| format!("copy {} -> {}: {}", src.display(), dst.display(), e))?;
    }
    Ok(())
}

fn prepare_adapter(
    setup_dir: &Path,
    adapter_dir: &Path,
    label: &str,
    force: bool,
) -> Result<(), String> {
    let snapshot = snapshot_setup(setup_dir)?;
    if adapter_dir.exists() {
        if !force {
            return Err(format!(
                "adapter directory {} already exists (use --force)",
                adapter_dir.display()
            ));
        }
        std::fs::remove_dir_all(adapter_dir)
            .map_err(|e| format!("removing {}: {}", adapter_dir.display(), e))?;
    }

    let input_dir = adapter_dir.join("input");
    let output_dir = adapter_dir.join("output");
    copy_required_params(setup_dir, &input_dir)?;
    std::fs::create_dir_all(&output_dir)
        .map_err(|e| format!("creating {}: {}", output_dir.display(), e))?;

    let manifest = AdapterManifest {
        version: 1,
        label: label.to_string(),
        created_at_unix: now_unix(),
        source_setup_dir: setup_dir.display().to_string(),
        source_digest_hex: snapshot.digest_hex.clone(),
        source_circuit_hashes: snapshot.circuit_hashes,
    };
    let manifest_path = adapter_manifest_path(adapter_dir);
    write_adapter_manifest(&manifest_path, &manifest)?;

    let instructions = adapter_dir.join("INSTRUCTIONS.txt");
    let mut f = File::create(&instructions)
        .map_err(|e| format!("creating {}: {}", instructions.display(), e))?;
    writeln!(
        f,
        "ZOKA phase2 adapter package\n\
         1) Read input/*.params as ceremony input.\n\
         2) Run external phase2 contribution flow.\n\
         3) Write resulting *.params into output/.\n\
         4) Run finalize-adapter to validate and produce canonical DIGEST."
    )
    .map_err(|e| format!("writing {}: {}", instructions.display(), e))?;

    println!(
        "adapter package prepared at {}\nsource digest: {}",
        adapter_dir.display(),
        manifest.source_digest_hex
    );
    Ok(())
}

fn finalize_adapter(
    adapter_dir: &Path,
    phase2_out_dir: &Path,
    out_setup_dir: &Path,
    transcript_path: Option<&Path>,
    contributor: &str,
    note: &str,
) -> Result<(), String> {
    let manifest_path = adapter_manifest_path(adapter_dir);
    let manifest = read_adapter_manifest(&manifest_path)?;
    if manifest.version != 1 {
        return Err(format!(
            "unsupported adapter manifest version: {}",
            manifest.version
        ));
    }

    let input_dir = adapter_dir.join("input");
    let mut changed = false;
    for circuit in setup_io::REQUIRED_CIRCUITS {
        let in_path = params_path(&input_dir, circuit)?;
        let out_path = params_path(phase2_out_dir, circuit)?;
        if !out_path.exists() {
            return Err(format!(
                "phase2 output missing required file {}",
                out_path.display()
            ));
        }
        if file_sha256_hex(&in_path)? != file_sha256_hex(&out_path)? {
            changed = true;
        }
    }
    if !changed {
        return Err(
            "phase2 output appears identical to adapter input; refusing finalize".to_string(),
        );
    }

    if out_setup_dir.exists() {
        std::fs::remove_dir_all(out_setup_dir)
            .map_err(|e| format!("removing {}: {}", out_setup_dir.display(), e))?;
    }
    std::fs::create_dir_all(out_setup_dir)
        .map_err(|e| format!("creating {}: {}", out_setup_dir.display(), e))?;

    copy_required_params(phase2_out_dir, out_setup_dir)?;
    let digest = setup_io::compute_directory_digest(out_setup_dir)
        .map_err(|e| format!("computing output digest: {}", e))?;
    setup_io::write_digest(out_setup_dir, &digest)
        .map_err(|e| format!("writing output DIGEST: {}", e))?;
    // Re-verify canonical output now that DIGEST is written.
    let out_snapshot = snapshot_setup(out_setup_dir)?;

    if let Some(tp) = transcript_path {
        if contributor.trim().is_empty() {
            return Err("--contributor is required when --transcript is provided".to_string());
        }
        let mut transcript = load_transcript(tp)?;
        let expected_before = transcript_tail_digest(&transcript).to_string();
        if expected_before != manifest.source_digest_hex {
            return Err(format!(
                "cannot append transcript: expected before digest {}, adapter source digest {}",
                expected_before, manifest.source_digest_hex
            ));
        }
        let index = transcript.contributions.len();
        transcript.contributions.push(ContributionRecord {
            index,
            timestamp_unix: now_unix(),
            contributor: contributor.to_string(),
            note: note.to_string(),
            before_digest_hex: manifest.source_digest_hex.clone(),
            after_digest_hex: out_snapshot.digest_hex.clone(),
            before_circuit_hashes: manifest.source_circuit_hashes,
            after_circuit_hashes: out_snapshot.circuit_hashes.clone(),
        });
        save_transcript(tp, &transcript)?;
        println!(
            "transcript updated at {} with contribution #{} by {}",
            tp.display(),
            index,
            contributor
        );
    }

    println!(
        "adapter finalized\nsource digest: {}\noutput digest: {}\noutput dir: {}",
        manifest.source_digest_hex,
        out_snapshot.digest_hex,
        out_setup_dir.display()
    );
    Ok(())
}

fn release_pin(
    setup_dir: &Path,
    transcript_path: Option<&Path>,
    out_env: Option<&Path>,
) -> Result<(), String> {
    let snapshot = snapshot_setup(setup_dir)?;
    let digest = snapshot.digest_hex;

    if let Some(tp) = transcript_path {
        let transcript = load_transcript(tp)?;
        let tail = transcript_tail_digest(&transcript);
        if tail != digest {
            return Err(format!(
                "transcript tail digest {} does not match setup digest {}",
                tail, digest
            ));
        }
    }

    let env_lines = format!(
        "ZOKA_TRUSTED_SETUP_DIR={}\nZOKA_EXPECTED_SETUP_DIGEST_COMPILED={}\n",
        setup_dir.display(),
        digest
    );
    if let Some(path) = out_env {
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() && !parent.exists() {
                std::fs::create_dir_all(parent)
                    .map_err(|e| format!("creating {}: {}", parent.display(), e))?;
            }
        }
        std::fs::write(path, env_lines.as_bytes())
            .map_err(|e| format!("writing {}: {}", path.display(), e))?;
        println!("release env file written at {}", path.display());
    }

    println!("release pin digest: {}", digest);
    println!(
        "ZOKA_EXPECTED_SETUP_DIGEST_COMPILED={} cargo build --release --bin zoka",
        digest
    );
    println!(
        "set ZOKA_EXPECTED_SETUP_DIGEST_COMPILED={}\ncargo build --release --bin zoka",
        digest
    );
    println!("{}", env_lines);
    Ok(())
}

fn compute_readiness_report(
    transcript_path: &Path,
    final_dir: &Path,
    min_unique_contributors: usize,
) -> Result<ReadinessReport, String> {
    let transcript = load_transcript(transcript_path)?;
    let tail_digest = transcript_tail_digest(&transcript).to_string();
    let final_snapshot = snapshot_setup(final_dir)?;
    if final_snapshot.digest_hex != tail_digest {
        return Err(format!(
            "readiness failed: transcript tail digest {} != final dir digest {}",
            tail_digest, final_snapshot.digest_hex
        ));
    }

    let mut unique = std::collections::BTreeSet::new();
    let mut all_mutate = true;
    for c in &transcript.contributions {
        unique.insert(c.contributor.trim().to_string());
        if c.before_digest_hex == c.after_digest_hex {
            all_mutate = false;
        }
    }

    let unique_count = unique.iter().filter(|s| !s.is_empty()).count();
    let ready = unique_count >= min_unique_contributors && all_mutate;

    Ok(ReadinessReport {
        transcript_path: transcript_path.display().to_string(),
        final_dir: final_dir.display().to_string(),
        tail_digest_hex: tail_digest,
        final_digest_hex: final_snapshot.digest_hex,
        contribution_count: transcript.contributions.len(),
        unique_contributors: unique_count,
        min_unique_contributors,
        all_contributions_mutate_state: all_mutate,
        ready,
    })
}

fn readiness_check(
    transcript_path: &Path,
    final_dir: &Path,
    min_unique_contributors: usize,
    out_json: Option<&Path>,
) -> Result<(), String> {
    let report = compute_readiness_report(transcript_path, final_dir, min_unique_contributors)?;
    if let Some(path) = out_json {
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() && !parent.exists() {
                std::fs::create_dir_all(parent)
                    .map_err(|e| format!("creating {}: {}", parent.display(), e))?;
            }
        }
        write_json_file(path, &report, "readiness report")?;
    }

    println!(
        "readiness: ready={} unique_contributors={}/{} contributions={} final_digest={}",
        report.ready,
        report.unique_contributors,
        report.min_unique_contributors,
        report.contribution_count,
        report.final_digest_hex
    );

    if !report.ready {
        return Err("ceremony readiness criteria not met".to_string());
    }
    Ok(())
}

fn write_json_file<T: Serialize>(path: &Path, value: &T, what: &str) -> Result<(), String> {
    let file = File::create(path).map_err(|e| format!("opening {}: {}", path.display(), e))?;
    let mut writer = BufWriter::new(file);
    serde_json::to_writer_pretty(&mut writer, value)
        .map_err(|e| format!("serializing {}: {}", what, e))?;
    writer
        .write_all(b"\n")
        .map_err(|e| format!("writing {}: {}", path.display(), e))?;
    writer
        .flush()
        .map_err(|e| format!("flushing {}: {}", path.display(), e))?;
    Ok(())
}

fn read_json_file<T: for<'de> Deserialize<'de>>(path: &Path, what: &str) -> Result<T, String> {
    let file = File::open(path).map_err(|e| format!("opening {}: {}", path.display(), e))?;
    let reader = BufReader::new(file);
    serde_json::from_reader(reader).map_err(|e| format!("parsing {}: {}", what, e))
}

fn publish_bundle(
    transcript_path: &Path,
    final_dir: &Path,
    out_dir: &Path,
    min_unique_contributors: usize,
    force: bool,
) -> Result<(), String> {
    let report = compute_readiness_report(transcript_path, final_dir, min_unique_contributors)?;
    if !report.ready {
        return Err("cannot publish bundle: ceremony readiness criteria not met".to_string());
    }
    let transcript = load_transcript(transcript_path)?;

    if out_dir.exists() {
        if !force {
            return Err(format!(
                "output directory {} already exists (use --force)",
                out_dir.display()
            ));
        }
        std::fs::remove_dir_all(out_dir)
            .map_err(|e| format!("removing {}: {}", out_dir.display(), e))?;
    }
    std::fs::create_dir_all(out_dir)
        .map_err(|e| format!("creating {}: {}", out_dir.display(), e))?;

    let transcript_out = out_dir.join("transcript.json");
    std::fs::copy(transcript_path, &transcript_out).map_err(|e| {
        format!(
            "copy {} -> {}: {}",
            transcript_path.display(),
            transcript_out.display(),
            e
        )
    })?;

    let setup_out = out_dir.join("setup");
    copy_required_params(final_dir, &setup_out)?;
    let digest_src = final_dir.join("DIGEST");
    let digest_out = setup_out.join("DIGEST");
    std::fs::copy(&digest_src, &digest_out).map_err(|e| {
        format!(
            "copy {} -> {}: {}",
            digest_src.display(),
            digest_out.display(),
            e
        )
    })?;

    let readiness_out = out_dir.join("readiness.json");
    write_json_file(&readiness_out, &report, "readiness report")?;

    let release_env_out = out_dir.join("RELEASE.env");
    let env_lines = format!(
        "ZOKA_TRUSTED_SETUP_DIR={}\nZOKA_EXPECTED_SETUP_DIGEST_COMPILED={}\n",
        final_dir.display(),
        report.final_digest_hex
    );
    std::fs::write(&release_env_out, env_lines.as_bytes())
        .map_err(|e| format!("writing {}: {}", release_env_out.display(), e))?;

    let mut files = Vec::new();
    files.push(PublishedFile {
        relative_path: "transcript.json".to_string(),
        sha256: file_sha256_hex(&transcript_out)?,
    });
    files.push(PublishedFile {
        relative_path: "readiness.json".to_string(),
        sha256: file_sha256_hex(&readiness_out)?,
    });
    files.push(PublishedFile {
        relative_path: "RELEASE.env".to_string(),
        sha256: file_sha256_hex(&release_env_out)?,
    });
    for circuit in setup_io::REQUIRED_CIRCUITS {
        let path = params_path(&setup_out, circuit)?;
        files.push(PublishedFile {
            relative_path: format!(
                "setup/{}",
                path.file_name()
                    .map(|s| s.to_string_lossy().to_string())
                    .unwrap_or_default()
            ),
            sha256: file_sha256_hex(&path)?,
        });
    }
    files.push(PublishedFile {
        relative_path: "setup/DIGEST".to_string(),
        sha256: file_sha256_hex(&digest_out)?,
    });
    files.sort_by(|a, b| a.relative_path.cmp(&b.relative_path));

    let mut contributor_set = std::collections::BTreeSet::new();
    for c in &transcript.contributions {
        let contributor = c.contributor.trim();
        if !contributor.is_empty() {
            contributor_set.insert(contributor.to_string());
        }
    }
    let contributors = contributor_set.into_iter().collect::<Vec<_>>();

    let manifest = CeremonyPublicationManifest {
        version: 1,
        created_at_unix: now_unix(),
        transcript_path: transcript_path.display().to_string(),
        final_dir: final_dir.display().to_string(),
        final_digest_hex: report.final_digest_hex.clone(),
        min_unique_contributors,
        unique_contributors: report.unique_contributors,
        contribution_count: report.contribution_count,
        contributors,
        files,
    };
    let manifest_out = out_dir.join("manifest.json");
    write_json_file(&manifest_out, &manifest, "publication manifest")?;

    println!(
        "publication bundle ready at {}\nfinal digest: {}\ncontributors: {}\nmanifest: {}",
        out_dir.display(),
        report.final_digest_hex,
        report.unique_contributors,
        manifest_out.display()
    );
    Ok(())
}

fn verify_bundle(bundle_dir: &Path) -> Result<(), String> {
    let manifest_path = bundle_dir.join("manifest.json");
    let readiness_path = bundle_dir.join("readiness.json");
    let transcript_path = bundle_dir.join("transcript.json");
    let setup_dir = bundle_dir.join("setup");

    let manifest: CeremonyPublicationManifest =
        read_json_file(&manifest_path, "publication manifest")?;
    let readiness: ReadinessReport = read_json_file(&readiness_path, "readiness report")?;
    let transcript = load_transcript(&transcript_path)?;

    if !readiness.ready {
        return Err("bundle readiness is false".to_string());
    }
    if readiness.final_digest_hex != manifest.final_digest_hex {
        return Err(format!(
            "readiness/manifest digest mismatch: {} != {}",
            readiness.final_digest_hex, manifest.final_digest_hex
        ));
    }
    if readiness.unique_contributors < manifest.min_unique_contributors {
        return Err(format!(
            "readiness unique contributors {} below manifest threshold {}",
            readiness.unique_contributors, manifest.min_unique_contributors
        ));
    }
    if transcript.contributions.len() != manifest.contribution_count {
        return Err(format!(
            "transcript contributions {} != manifest {}",
            transcript.contributions.len(),
            manifest.contribution_count
        ));
    }
    let tail = transcript_tail_digest(&transcript).to_string();
    if tail != manifest.final_digest_hex {
        return Err(format!(
            "transcript tail digest {} != manifest final digest {}",
            tail, manifest.final_digest_hex
        ));
    }

    let computed_digest = setup_io::verify_directory_digest(&setup_dir)
        .map_err(|e| format!("invalid setup/: {}", e))?;
    let computed_digest_hex = hex::encode(computed_digest);
    if computed_digest_hex != manifest.final_digest_hex {
        return Err(format!(
            "setup/ DIGEST mismatch: computed {} != manifest {}",
            computed_digest_hex, manifest.final_digest_hex
        ));
    }

    for file in &manifest.files {
        let absolute = bundle_dir.join(&file.relative_path);
        if !absolute.exists() {
            return Err(format!("bundle file missing: {}", absolute.display()));
        }
        let actual = file_sha256_hex(&absolute)?;
        if actual != file.sha256 {
            return Err(format!(
                "file hash mismatch for {}: {} != {}",
                file.relative_path, actual, file.sha256
            ));
        }
    }

    println!(
        "bundle verified: {}\nfinal digest: {}\ncontributors: {}\nfiles: {}",
        bundle_dir.display(),
        manifest.final_digest_hex,
        manifest.unique_contributors,
        manifest.files.len()
    );
    Ok(())
}
